1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single source of truth for an owner's membership scoring: the {@code membershipPoints} an owner
9	 * has earned and the {@code membershipLevel} those points band into, plus the fiscal-year primitive
10	 * both the scoring's tenure rule and the owner's fiscal/membership-number formatting share.
11	 *
12	 * <p>These are pure functions of an owner's already-stored fields; {@link OwnerMapper} delegates its
13	 * {@code membershipPoints}, {@code membershipLevel}, {@code fiscalYear} and {@code membershipNumber}
14	 * derivations here, mirroring how it delegates to {@link OwnerIdentity} and {@link OwnerRegion}.
15	 */
16	public final class OwnerMembership {
17	
18	    private OwnerMembership() {
19	    }
20	
21	    /**
22	     * The fiscal year the {@code date} falls in, as an integer. The fiscal year starts on 1 July and is
23	     * named by the calendar year in which it ends, so 1 July 2026 - 30 June 2027 is fiscal year 2027: a
24	     * date in July or later belongs to the next calendar year's fiscal year, an earlier date to the
25	     * current calendar year's.
26	     */
27	    public static int fiscalYearOf(LocalDate date) {
28	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
29	    }
30	
31	    /**
32	     * The two-digit fiscal-year code for {@code date}: the {@link #fiscalYearOf(LocalDate) fiscal year}
33	     * it falls in taken mod 100 and zero-padded to two digits (e.g. {@code 27}). This is the shared
34	     * fiscal-year segment behind the mapper's {@code fiscalYear} ({@code FY27}) and
35	     * {@code membershipNumber} ({@code ...-M27}).
36	     */
37	    public static String fiscalYearCode(LocalDate date) {
38	        return String.format("%02d", fiscalYearOf(date) % 100);
39	    }
40	
41	    /**
42	     * The owner's membership points. Starts at 0; add 2 when an email is present; add 1 when the owner's
43	     * name was unique on creation (namesakeCount is 0); add 2 for a household of 3 or more members; add 3
44	     * for tenure of one or more elapsed fiscal years (the current fiscal year differs from the fiscal
45	     * year the registrationDate falls in; fiscal year starting 1 July).
46	     */
47	    public static int points(Owner owner) {
48	        int points = 0;
49	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
50	        if (hasEmail) {
51	            points += 2;
52	        }
53	        Integer namesakeCount = owner.getNamesakeCount();
54	        if (namesakeCount != null && namesakeCount == 0) {
55	            points += 1;
56	        }
57	        Integer householdSize = owner.getHouseholdSize();
58	        if (householdSize != null && householdSize >= 3) {
59	            points += 2;
60	        }
61	        if (owner.getRegistrationDate() != null
62	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(owner.getRegistrationDate()) >= 1) {
63	            points += 3;
64	        }
65	        return points;
66	    }
67	
68	    /**
69	     * The owner's membership level, derived by banding {@link #points(Owner)}: level 1 for 0-1 points,
70	     * level 2 for 2-3, level 3 for 4-5, level 4 for 6 or more.
71	     *
72	     * <p>When a {@code membershipLevelCap} is recorded (set at creation from the owner's household — see
73	     * {@link CapMembershipLevel}), the banded level is capped to it: a new owner's level cannot exceed
74	     * one above the current maximum level among their household members. A null cap (no existing
75	     * household member) leaves the banded level unchanged.
76	     */
77	    public static int level(Owner owner) {
78	        int level;
79	        int points = points(owner);
80	        if (points >= 6) {
81	            level = 4;
82	        }
83	        else if (points >= 4) {
84	            level = 3;
85	        }
86	        else if (points >= 2) {
87	            level = 2;
88	        }
89	        else {
90	            level = 1;
91	        }
92	        Integer cap = owner.getMembershipLevelCap();
93	        if (cap != null && level > cap) {
94	            level = cap;
95	        }
96	        return level;
97	    }
98	}
