1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single source of truth for an owner's canonical region, derived from the postcode and city. A
7	 * region is a short code (NSW, VIC, QLD) fixed by two lookup tables: the inclusive 4-digit postcode
8	 * range per region, and the city-to-region fallback used when the postcode yields nothing.
9	 *
10	 * <p>{@link #fromPostcode} answers the region for a postcode alone (or {@code null}) and is the source
11	 * of the REGION component of an owner's {@code customerCode}; {@link #regionOf} reads that component
12	 * back out of a {@code customerCode}, which is how a whole owner resolves to a locality.
13	 */
14	public final class OwnerRegion {
15	
16	    /** City -> canonical region, from the fixed city-to-region table. */
17	    private static final Map<String, String> CITY_REGION = Map.of(
18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
22	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
23	
24	    /** Region -> IANA timezone name, from the fixed region-to-timezone table. */
25	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
26	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
27	
28	    private OwnerRegion() {
29	    }
30	
31	    /** The canonical region for {@code city} from the fixed city-to-region table, or {@code null}. */
32	    static String regionForCity(String city) {
33	        return city == null ? null : CITY_REGION.get(city);
34	    }
35	
36	    /** The inclusive 4-digit postcode range {low, high} for {@code region}, or {@code null}. */
37	    static int[] rangeForRegion(String region) {
38	        return REGION_RANGE.get(region);
39	    }
40	
41	    /**
42	     * The region whose fixed range contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
43	     * QLD 4000-4099), or {@code null} when the postcode is absent, non-numeric, or in no known range.
44	     */
45	    public static String fromPostcode(String postcode) {
46	        if (postcode == null || postcode.isBlank()) {
47	            return null;
48	        }
49	        int value;
50	        try {
51	            value = Integer.parseInt(postcode.trim());
52	        }
53	        catch (NumberFormatException ex) {
54	            return null;
55	        }
56	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
57	            int[] range = entry.getValue();
58	            if (value >= range[0] && value <= range[1]) {
59	                return entry.getKey();
60	            }
61	        }
62	        return null;
63	    }
64	
65	    /**
66	     * The REGION component of a {@code customerCode} ({@code <REGION>-<HASH8>}) — the owner's locality.
67	     * Now that identity is region-and-hash, the locality is read straight off the assigned code rather
68	     * than recomputed, so it always matches the code. {@code UNKNOWN} when the code is absent or has no
69	     * region component.
70	     */
71	    public static String regionOf(String customerCode) {
72	        if (customerCode == null) {
73	            return "UNKNOWN";
74	        }
75	        int dash = customerCode.indexOf('-');
76	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
77	    }
78	
79	    /**
80	     * The IANA timezone name for the owner's region, resolved from the REGION component of the
81	     * {@code customerCode} through the fixed region-to-timezone table (NSW -> Australia/Sydney,
82	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). {@code null} when the region is
83	     * absent or unknown.
84	     */
85	    public static String timezoneOf(String customerCode) {
86	        return REGION_TIMEZONE.get(regionOf(customerCode));
87	    }
88	}
