1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
12	 * region code derived from the postcode (NSW/VIC/QLD, else {@code UNKNOWN}) and HASH8 is the first 8
13	 * upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName} (e.g.
14	 * {@code NSW-1A2B3C4D}). The base code is fully determined by the owner's region and hashed identity.
15	 *
16	 * <p>When that base code collides with an existing owner's {@code customerCode}, it is de-duplicated
17	 * by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique (e.g.
18	 * {@code NSW-1A2B3C4D-2}). Runs before {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns
19	 * only the owners that predate this create.
20	 */
21	public class AssignCustomerCode {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        owner.setCustomerCode(uniqueCode(baseCode(owner), assignedCodes(ownerRepository)));
25	    }
26	
27	    /**
28	     * The owner's base code before any collision suffix, formatted {@code <REGION>-<HASH8>}: REGION is
29	     * the region derived from the postcode ({@code UNKNOWN} when none), HASH8 the owner's hashed
30	     * identity. Fully determined by the owner, so equal owners produce the same base.
31	     */
32	    private static String baseCode(Owner owner) {
33	        String region = OwnerRegion.fromPostcode(owner.getPostcode());
34	        if (region == null) {
35	            region = "UNKNOWN";
36	        }
37	        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
38	        return region + "-" + hash8;
39	    }
40	
41	    /**
42	     * {@code base} de-duplicated against {@code existing} by appending {@code -<n>} with the smallest
43	     * {@code n} of 2 or more that makes it unique (e.g. {@code NSW-1A2B3C4D-2}); {@code base} itself
44	     * when already free.
45	     */
46	    private static String uniqueCode(String base, Set<String> existing) {
47	        String code = base;
48	        for (int n = 2; existing.contains(code); n++) {
49	            code = base + "-" + n;
50	        }
51	        return code;
52	    }
53	
54	    /** The codes already assigned to existing owners — the set a new code must avoid colliding with. */
55	    private static Set<String> assignedCodes(OwnerRepository ownerRepository) {
56	        Set<String> existing = new HashSet<>();
57	        for (Owner other : ownerRepository.findAll()) {
58	            if (other.getCustomerCode() != null) {
59	                existing.add(other.getCustomerCode());
60	            }
61	        }
62	        return existing;
63	    }
64	}
