1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.points(owner))")
32	    @Mapping(target = "membershipLevel",
33	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.level(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
37	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
38	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
39	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * The owner's canonical URL, formatted {@code '/api/owners/<id>'} where id is the owner's id.
44	     * Null when the owner has no id yet.
45	     */
46	    default String selfLink(Owner owner) {
47	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
48	    }
49	
50	    /**
51	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
52	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
53	     * telephone is recorded.
54	     */
55	    default String telephoneDisplay(Owner owner) {
56	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
57	                owner.getTelephone());
58	    }
59	
60	    /**
61	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
62	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
63	     * birth date is recorded.
64	     */
65	    default String ageBand(Owner owner) {
66	        if (owner.getBirthDate() == null) {
67	            return null;
68	        }
69	        java.time.LocalDate reference = owner.getRegistrationDate() != null
70	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
71	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
72	        if (age < 18) {
73	            return "MINOR";
74	        }
75	        if (age < 65) {
76	            return "ADULT";
77	        }
78	        return "SENIOR";
79	    }
80	
81	    /**
82	     * The owner's derived {@code identityKey} = SHA-256 hex over
83	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, the single key all
84	     * duplicate detection is expressed through.
85	     */
86	    default String identityKey(Owner owner) {
87	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
88	                owner.getTelephone(), owner.getEmail(), owner.getLastName());
89	    }
90	
91	    /**
92	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}: one of {@code PREMIUM_METRO},
93	     * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}. TIER is
94	     * {@code PREMIUM} when membershipLevel is 3 or more, otherwise {@code STANDARD}. AREA is
95	     * {@code METRO} when the locality is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
96	     */
97	    default String ownerSegment(Owner owner) {
98	        String tier = org.springframework.samples.petclinic.rest.function.owner.OwnerMembership
99	                .level(owner) >= 3 ? "PREMIUM" : "STANDARD";
100	        String locality = locality(owner);
101	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
102	        return tier + "_" + (metro ? "METRO" : "REGIONAL");
103	    }
