115	     * when a title is present, or just the {@code lastName} when no title is given.
116	     */
117	    default String salutation(Owner owner) {
118	        String title = owner.getTitle();
119	        if (title == null || title.isBlank()) {
120	            return owner.getLastName();
121	        }
122	        return title + " " + owner.getLastName();
123	    }
124	
125	    default String initials(Owner owner) {
126	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
127	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
128	    }
129	
130	    /**
131	     * The owner's locality (region), read from the REGION component of the customerCode
132	     * ({@code <REGION>-<HASH8>}); see
133	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
134	     */
135	    default String locality(Owner owner) {
136	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
137	                owner.getCustomerCode());
138	    }
139	
140	    /**
141	     * The IANA timezone name for the owner's locality (region), from the fixed region-to-timezone
142	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane); see
143	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#timezoneOf}.
144	     * Null when the region is absent or unknown.
145	     */
146	    default String timezone(Owner owner) {
147	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.timezoneOf(
148	                owner.getCustomerCode());
149	    }
150	
151	    /**
152	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode};
153	     * see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity#luhnCheckDigit}.
154	     * Null when the customer code is absent.
155	     */
156	    default Integer checkDigit(Owner owner) {
