3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	import tools.jackson.databind.json.JsonMapper;
12	
13	/**
14	 * Emits, on the dedicated {@code AUDIT} logger, the record of a newly created owner. Runs after the
15	 * owner has been saved so its id is available. Two things are emitted:
16	 *
17	 * <ol>
18	 * <li>a human-readable audit line (id, customerCode, registrationDate, membershipLevel,
19	 * membershipNumber); and</li>
20	 * <li>an immutable structured {@link OwnerCreatedEvent} serialised to JSON, so audit consumers have a
21	 * machine-parseable, ordered event to react to.</li>
22	 * </ol>
23	 */
24	public class AuditOwnerCreated {
25	
26	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
27	
28	    private static final JsonMapper JSON = JsonMapper.builder().build();
29	
30	    /** Monotonically increasing sequence stamped onto each event, shared across all creates. */
31	    private static final AtomicLong SEQUENCE = new AtomicLong();
32	
33	    public void service(@Val Owner owner, OwnerMapper mapper) {
34	        int membershipLevel = OwnerMembership.level(owner);
35	
36	        AUDIT.info(
37	                "Created owner id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
38	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
39	                membershipLevel, mapper.membershipNumber(owner));
40	
41	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
42	                primaryIdentifier(owner), membershipLevel);
43	        AUDIT.info(JSON.writeValueAsString(event));
44	    }
45	
46	    /**
47	     * The owner's current primary identifier carried by the {@link OwnerCreatedEvent}. Today that is the
48	     * {@code customerCode}; when the customerCode is unified into the memberId, return the memberId here
49	     * and the event will carry it instead. This single method is the one place the event's identity
50	     * source is defined, so that later switch is a one-line change.
51	     */
52	    private static String primaryIdentifier(Owner owner) {
53	        return owner.getCustomerCode();
54	    }
55	}
