1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event emitted on the dedicated {@code AUDIT} logger when an owner is
5	 * created. Serialised to JSON as {@code {seq, ownerId, customerCode, membershipLevel, event}}.
6	 *
7	 * <p>{@code seq} is a monotonically increasing sequence stamped across all creates, so events can be
8	 * totally ordered. {@code customerCode} carries the owner's <em>current primary identifier</em>: it is
9	 * the customerCode today and whatever replaces it later — see {@link AuditOwnerCreated#primaryIdentifier}
10	 * — so the event contract survives the identifier being unified into the memberId.
11	 *
12	 * <p>Being a record, every field is final and the event cannot be mutated after it is emitted.
13	 */
14	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel,
15	        String event) {
16	
17	    /** The marker naming this kind of event. */
18	    public static final String OWNER_CREATED = "OWNER_CREATED";
19	
20	    /** Builds an {@link #OWNER_CREATED} event; the {@code event} marker is fixed. */
21	    public OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel) {
22	        this(seq, ownerId, customerCode, membershipLevel, OWNER_CREATED);
23	    }
24	}
