1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's deterministic {@code householdId} — the first 12 hex characters of SHA-256 over
9	 * the normalized lastName and postcode (see {@link OwnerIdentity#deriveHouseholdId}). Because the id
10	 * is a pure function of (lastName, postcode), every owner that shares a lastName and postcode resolves
11	 * to the same value automatically, with no back-filling and regardless of creation order. It also
12	 * records {@code householdSize} — the number of owners that share this household after the create
13	 * (the existing members with the same computed householdId, plus this new owner). Runs before
14	 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
15	 * create.
16	 */
17	public class AssignHouseholdId {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = OwnerIdentity.householdIdOf(owner.getLastName(), owner.getPostcode());
21	        owner.setHouseholdId(householdId);
22	
23	        // Count the existing members of this household (same computed householdId) plus this owner.
24	        int size = 1;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            String existingHousehold = OwnerIdentity.householdIdOf(
27	                    existing.getLastName(), existing.getPostcode());
28	            if (householdId.equals(existingHousehold)) {
29	                size++;
30	            }
31	        }
32	        owner.setHouseholdSize(size);
33	    }
34	}
