1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate check for {@code POST /api/owners}, keyed on the whole {@code identityKey} — the
11	 * single source of truth for duplicate detection (see {@link OwnerIdentity}). Two owners are
12	 * duplicates only when their <em>whole</em> identityKey
13	 * (SHA-256 hex over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
14	 * equal; because the telephone is part of the key, two owners with the same last name and postcode but
15	 * different telephones have different identityKeys and are both allowed — the postcode no longer feeds
16	 * this check, so there is no separate household-duplicate 409. On an exact full-key match it throws
17	 * {@link DuplicateIdentityException}, handled globally as 409. A request that sets
18	 * {@code sharesHousehold} bypasses the check entirely.
19	 */
20	public class EnsureIdentityUnique {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateIdentityException {
24	        // A declared household member is allowed to join an existing household, so it bypasses the
25	        // duplicate block entirely.
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return;
28	        }
29	
30	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
31	                request.getLastName());
32	        for (Owner existing : ownerRepository.findAll()) {
33	            // A soft-deleted owner no longer blocks a create.
34	            if (Boolean.TRUE.equals(existing.getDeleted())) {
35	                continue;
36	            }
37	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
38	                    existing.getLastName());
39	            if (identityKey.equals(existingKey)) {
40	                throw new DuplicateIdentityException(identityKey);
41	            }
42	        }
43	    }
44	}
