7	/**
8	 * Records the new owner's {@code membershipLevelCap}: the ceiling its membership level may reach,
9	 * being one above the current maximum {@link OwnerMembership#level(Owner) membershipLevel} among the
10	 * existing members of its household (those sharing the owner's computed {@code householdId}). With no
11	 * existing household member the cap is left unset (null), so no cap applies.
12	 *
13	 * <p>Runs after {@link AssignHouseholdId} (so the owner's {@code householdId} is set) and before
14	 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
15	 * create. {@link OwnerMembership#level(Owner)} applies the recorded cap.
16	 */
17	public class CapMembershipLevel {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null) {
22	            return;
23	        }
24	        Integer maxLevel = null;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            String existingHousehold = OwnerIdentity.householdIdOf(
27	                    existing.getLastName(), existing.getPostcode());
28	            if (householdId.equals(existingHousehold)) {
29	                int level = OwnerMembership.level(existing);
30	                if (maxLevel == null || level > maxLevel) {
31	                    maxLevel = level;
32	                }
33	            }
34	        }
35	        if (maxLevel != null) {
36	            owner.setMembershipLevelCap(maxLevel + 1);
