3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a create as a soft duplicate. Runs before {@link SaveOwner}, so
10	 * {@link OwnerRepository#findAll()} returns only the owners that predate this create. A new owner
11	 * that {@link EnsureIdentityUnique} already cleared as not a hard duplicate is nonetheless a
12	 * <em>possible</em> duplicate when an existing owner has a <em>different</em> identityKey yet shares
13	 * its {@code soundex(lastName)} and its postcode — for instance the same household reached under a
14	 * different telephone. On such a match it sets {@code possibleDuplicate} true and
15	 * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match); the
16	 * owner is still created. With no match it sets {@code possibleDuplicate} false and leaves
17	 * {@code possibleDuplicateOf} null.
18	 *
19	 * <p>An owner created with {@code sharesHousehold} is a <em>declared</em> household member — it
20	 * deliberately joins an existing household — so it is never a suspected duplicate and is left
21	 * unflagged.
22	 */
23	public class FlagPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
26	        owner.setPossibleDuplicate(false);
27	        owner.setPossibleDuplicateOf(null);
28	
29	        // A declared household member is not a suspected duplicate.
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return;
32	        }
33	
34	        // A soft match keys on a shared postcode; an owner with no postcode cannot share one.
35	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
36	            return;
37	        }
38	
39	        Owner match = null;
40	        for (Owner existing : ownerRepository.findAll()) {
41	            // A soft-deleted owner is not a duplicate match.
42	            if (Boolean.TRUE.equals(existing.getDeleted())) {
43	                continue;
44	            }
45	            if (!isPossibleDuplicate(owner, existing)) {
46	                continue;
47	            }
48	            if (match == null || existing.getId() < match.getId()) {
49	                match = existing;
50	            }
51	        }
52	
53	        if (match != null) {
54	            owner.setPossibleDuplicate(true);
55	            owner.setPossibleDuplicateOf(match.getId());
56	        }
57	    }
58	
59	    /**
60	     * Whether {@code existing} is a soft duplicate of the new {@code owner}: it shares the
61	     * {@code soundex(lastName)} and the postcode but resolves to a different identityKey. An identical
62	     * identityKey is a hard duplicate ({@link EnsureIdentityUnique}), not the soft match.
63	     */
64	    private static boolean isPossibleDuplicate(Owner owner, Owner existing) {
65	        if (!OwnerIdentity.soundex(owner.getLastName())
66	                .equals(OwnerIdentity.soundex(existing.getLastName()))) {
67	            return false;
68	        }
69	        if (!owner.getPostcode().equals(existing.getPostcode())) {
70	            return false;
71	        }
72	        return !OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName())
73	                .equals(OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
74	                        existing.getLastName()));
75	    }
76	}
