                letters.append(Character.toUpperCase(c));
            }
        }
        if (letters.length() == 0) {
            return "";
        }
        char[] out = { letters.charAt(0), '0', '0', '0' };
        int count = 1;
        char last = mappingCode(letters, 0);
        for (int i = 1; i < letters.length() && count < 4; i++) {
            char mapped = mappingCode(letters, i);
            if (mapped != 0) {
                if (mapped != '0' && mapped != last) {
                    out[count++] = mapped;
                }
                last = mapped;
            }
